def _resolve_format(text: str, fmt: str | None) -> tuple[str, list[str]]:
    """Возвращает (формат, имена колонок заголовка в нижнем регистре)."""
    if fmt is not None and fmt not in _SPECS:
        raise UnknownFormatError(f"unknown format {fmt!r}", line_no=1)
    candidates = [fmt] if fmt is not None else list(_SPECS)
    matched = []
    for name in candidates:
