    m = _SFERA_AMOUNT.match(value.strip())
    if not m or (m.group(1) and not allow_sign):
        raise ValidationError(f"invalid amount: {value!r}")
    number = _THOUSANDS.sub("", m.group(2)).replace(",", ".")
    return parse_amount(m.group(1) + number)


def _parse_nova(fields: list[str], idx: dict[str, int], imported_at: dt.datetime) -> Transaction:
    raw_date = fields[idx["date"]]
    try:
        date = dt.date.fromisoformat(raw_date.strip())
    except ValueError as exc:
        raise ValidationError(f"invalid date {raw_date!r}") from exc
    return Transaction(
        date=date,
        amount=parse_amount(fields[idx["amount"]]),
        description=fields[idx["description"]].strip(),
        imported_at=imported_at,
    )


def _parse_sfera(fields: list[str], idx: dict[str, int], imported_at: dt.datetime) -> Transaction:
