        amount=_parse_sfera_amount(fields[idx["сумма"]], allow_sign=True),
        description=fields[idx["описание"]].strip(),
        imported_at=imported_at,
    )


def _split_column(value: str) -> Decimal | None:
    """Сумма колонки или None, если колонка пуста (пробелы или 0,00)."""
    if not value.strip():
        return None
    amount = _parse_sfera_amount(value, allow_sign=False)
    return amount if amount != 0 else None


def _parse_sfera_split(
    fields: list[str], idx: dict[str, int], imported_at: dt.datetime
) -> Transaction:
    date = _parse_sfera_date(fields[idx["дата"]])
    income = _split_column(fields[idx["приход"]])
    expense = _split_column(fields[idx["расход"]])
    if income is not None and expense is not None:
        raise ValidationError("both income and expense are filled")
    if income is None and expense is None:
        raise ValidationError("neither income nor expense is filled")
    return Transaction(
        date=date,
        amount=income if income is not None else -expense,
        description=fields[idx["описание"]].strip(),
        imported_at=imported_at,
    )


_PARSERS: dict[str, Callable[[list[str], dict[str, int], dt.datetime], Transaction]] = {
    "nova": _parse_nova,
    "sfera": _parse_sfera,
    "sfera_split": _parse_sfera_split,
}

_JUNK = re.compile(r"[\s;,]*")


def _is_junk(fields: list[str]) -> bool:
    return all(_JUNK.fullmatch(f) for f in fields)


def _tx_key(tx: Transaction) -> tuple[dt.date, Decimal, str]:
    return (tx.date, tx.amount, normalize_description(tx.description))


def import_statement(
    path: str | os.PathLike[str],
    store: MemoryStore,
    *,
    fmt: str | None = None,
    strict: bool = False,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> ImportResult:
    """Импортирует выписку в store.

    Весь файл разбирается до записи; новые транзакции пишутся одним add_many.
    Дубли — то, что уже было в store до импорта, с учётом количества.
    """
    clock = clock or SystemClock()
    text, encoding = _decode(path)
    fmt_name, header = _resolve_format(text, fmt)
    spec = _SPECS[fmt_name]
    parse = _PARSERS[fmt_name]
    idx = {c: header.index(c) for c in spec.columns}
    needed = max(idx.values()) + 1
    imported_at = clock.now()

    existing = Counter(_tx_key(tx) for tx in store.all())
    new: list[Transaction] = []
    errors: list[RowError] = []
    duplicates = 0

    reader = csv.reader(io.StringIO(text, newline=""), delimiter=spec.delimiter)
    next(reader)  # заголовок, уже разобран
    prev_line = reader.line_num
    while True:
        line_no = prev_line + 1
        try:
            fields = next(reader)
        except StopIteration:
            break
        except csv.Error as exc:
            prev_line = reader.line_num
            message = str(exc)
            if strict:
                raise StatementRowError(message, line_no=line_no) from exc
            errors.append(RowError(line_no, message))
            continue
        prev_line = reader.line_num
        if _is_junk(fields):
            continue
        try:
            if len(fields) < needed:
                raise ValidationError("not enough fields")
            tx = parse(fields, idx, imported_at)
        except ValidationError as exc:
            if strict:
                raise StatementRowError(str(exc), line_no=line_no) from exc
            errors.append(RowError(line_no, str(exc)))
            continue
        key = _tx_key(tx)
        if existing[key] > 0:
            existing[key] -= 1
            duplicates += 1
            continue
        if categorizer is not None:
            category = categorizer.categorize(tx)
            if category is not None:
                tx = replace(tx, category=category)
        new.append(tx)

    if new:
        store.add_many(new)
    logger.info(
        "imported %d transactions from %s (%s, %d duplicates, %d errors)",
        len(new), path, fmt_name, duplicates, len(errors),
    )
    return ImportResult(
        format=fmt_name,
        encoding=encoding,
        added=len(new),
        duplicates=duplicates,
        errors=errors,
    )


def import_csv(
    path: str | os.PathLike[str],
    store: MemoryStore,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> int:
    """Импортирует выписку в store и возвращает число добавленных транзакций."""
    result = import_statement(path, store, strict=True, categorizer=categorizer, clock=clock)
    return result.added
