    if new:
        store.add_many(new)
    logger.info(
        "imported %d transactions from %s (%s, %d duplicates, %d errors)",
        len(new), path, fmt_name, duplicates, len(errors),
    )
    return ImportResult(
        format=fmt_name,
        encoding=encoding,
        added=len(new),
