"""Импорт банковских выписок.

Поддерживаются форматы:

    nova         date,amount,description            (разделитель «,», дата ГГГГ-ММ-ДД)
    sfera        Дата;Сумма;Описание                (разделитель «;», дата ДД.ММ.ГГГГ)
    sfera_split  Дата;Описание;Приход;Расход        (суммы без знака)

Нужные колонки ищутся по названию (без учёта регистра и пробелов по краям),
лишние колонки игнорируются. Кодировка — UTF-8 (BOM допустим), иначе cp1251.
"""

from __future__ import annotations

import csv
import datetime as dt
import io
import logging
import os
import re
from collections import Counter
from dataclasses import dataclass, replace
from decimal import Decimal
from pathlib import Path
from typing import Callable

from ledger.clock import Clock, SystemClock
from ledger.errors import StatementRowError, UnknownFormatError, ValidationError
from ledger.models import Transaction, parse_amount
from ledger.rules import Categorizer, normalize_text
from ledger.storage import MemoryStore

logger = logging.getLogger(__name__)

NOVA_COLUMNS = ("date", "amount", "description")

_SFERA_DATE = re.compile(r"^([0-9]{2})\.([0-9]{2})\.([0-9]{4})$")
_SFERA_AMOUNT = re.compile(
    r"^([+-]?)(([0-9]{1,3}([   ][0-9]{3})+|[0-9]+)(,[0-9]{1,2})?)$"
)
_THOUSANDS = re.compile(r"[   ]")
_JUNK = re.compile(r"[\s;,]*")


@dataclass(frozen=True)
class RowError:
    line_no: int
    message: str


@dataclass(frozen=True)
class ImportResult:
    format: str
    encoding: str
    added: int
    duplicates: int
    errors: list[RowError]


@dataclass(frozen=True)
class _Spec:
    delimiter: str
    columns: tuple[str, ...]  # нужные колонки в нижнем регистре


_SPECS: dict[str, _Spec] = {
    "nova": _Spec(",", NOVA_COLUMNS),
    "sfera": _Spec(";", ("дата", "сумма", "описание")),
    "sfera_split": _Spec(";", ("дата", "описание", "приход", "расход")),
}


def normalize_description(text: str) -> str:
    """Нормализует описание для сравнения (то же, что rules.normalize_text)."""
    return normalize_text(text)


def _decode(path: str | os.PathLike[str]) -> tuple[str, str]:
    data = Path(path).read_bytes()
    try:
        return data.decode("utf-8-sig"), "utf-8"
    except UnicodeDecodeError:
        pass
    try:
        return data.decode("cp1251"), "cp1251"
    except UnicodeDecodeError as exc:
        raise UnknownFormatError("file is neither utf-8 nor cp1251") from exc


def _header_columns(text: str, delimiter: str) -> list[str] | None:
    try:
        header = next(csv.reader(io.StringIO(text, newline=""), delimiter=delimiter), None)
    except csv.Error:
        return None
    if header is None:
        return None
    return [name.strip().casefold() for name in header]


def _resolve_format(text: str, fmt: str | None) -> tuple[str, list[str]]:
    """Возвращает (формат, имена колонок заголовка в нижнем регистре)."""
    if fmt is not None and fmt not in _SPECS:
        raise UnknownFormatError(f"unknown format {fmt!r}", line_no=1)
    candidates = [fmt] if fmt is not None else list(_SPECS)
    matched = []
    for name in candidates:
        spec = _SPECS[name]
        header = _header_columns(text, spec.delimiter)
        if header is not None and all(c in header for c in spec.columns):
            matched.append((name, header))
    if len(matched) != 1:
        if fmt is not None:
            raise UnknownFormatError(f"header does not match format {fmt!r}", line_no=1)
        reason = "ambiguous header" if matched else "unrecognized header"
        raise UnknownFormatError(reason, line_no=1)
    return matched[0]


def detect_format(path: str | os.PathLike[str]) -> str:
    """Определяет формат выписки по заголовку: "nova", "sfera" или "sfera_split"."""
    text, _ = _decode(path)
    return _resolve_format(text, None)[0]


def _parse_sfera_date(value: str) -> dt.date:
    m = _SFERA_DATE.match(value.strip())
    if not m:
        raise ValidationError(f"invalid date {value!r}")
    try:
        return dt.date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
    except ValueError as exc:
        raise ValidationError(f"invalid date {value!r}") from exc


def _parse_sfera_amount(value: str, *, allow_sign: bool) -> Decimal:
    m = _SFERA_AMOUNT.match(value.strip())
    if not m or (m.group(1) and not allow_sign):
        raise ValidationError(f"invalid amount: {value!r}")
    number = _THOUSANDS.sub("", m.group(2)).replace(",", ".")
    return parse_amount(m.group(1) + number)


def _parse_nova(fields: list[str], idx: dict[str, int], imported_at: dt.datetime) -> Transaction:
    raw_date = fields[idx["date"]]
    try:
        date = dt.date.fromisoformat(raw_date.strip())
    except ValueError as exc:
        raise ValidationError(f"invalid date {raw_date!r}") from exc
    return Transaction(
        date=date,
        amount=parse_amount(fields[idx["amount"]]),
        description=fields[idx["description"]].strip(),
        imported_at=imported_at,
    )


def _parse_sfera(fields: list[str], idx: dict[str, int], imported_at: dt.datetime) -> Transaction:
    return Transaction(
        date=_parse_sfera_date(fields[idx["дата"]]),
        amount=_parse_sfera_amount(fields[idx["сумма"]], allow_sign=True),
        description=fields[idx["описание"]].strip(),
        imported_at=imported_at,
    )


def _split_column(value: str) -> Decimal | None:
    """Сумма колонки или None, если колонка пуста (пробелы или 0,00)."""
    if not value.strip():
        return None
    amount = _parse_sfera_amount(value, allow_sign=False)
    return amount if amount != 0 else None


def _parse_sfera_split(
    fields: list[str], idx: dict[str, int], imported_at: dt.datetime
) -> Transaction:
    date = _parse_sfera_date(fields[idx["дата"]])
    income = _split_column(fields[idx["приход"]])
    expense = _split_column(fields[idx["расход"]])
    if income is not None and expense is not None:
        raise ValidationError("both income and expense are filled")
    if income is None and expense is None:
        raise ValidationError("neither income nor expense is filled")
    return Transaction(
        date=date,
        amount=income if income is not None else -expense,
        description=fields[idx["описание"]].strip(),
        imported_at=imported_at,
    )


_PARSERS: dict[str, Callable[[list[str], dict[str, int], dt.datetime], Transaction]] = {
    "nova": _parse_nova,
    "sfera": _parse_sfera,
    "sfera_split": _parse_sfera_split,
}


def _is_junk(fields: list[str]) -> bool:
    return all(_JUNK.fullmatch(f) for f in fields)


def _tx_key(tx: Transaction) -> tuple[dt.date, Decimal, str]:
    return (tx.date, tx.amount, normalize_description(tx.description))


def import_statement(
    path: str | os.PathLike[str],
    store: MemoryStore,
    *,
    fmt: str | None = None,
    strict: bool = False,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> ImportResult:
    """Импортирует выписку в store.

    Весь файл разбирается до записи; новые транзакции пишутся одним add_many.
    Дубли — то, что уже было в store до импорта, с учётом количества.
    """
    clock = clock or SystemClock()
    text, encoding = _decode(path)
    fmt_name, header = _resolve_format(text, fmt)
    spec = _SPECS[fmt_name]
    parse = _PARSERS[fmt_name]
    idx = {c: header.index(c) for c in spec.columns}
    needed = max(idx.values()) + 1
    imported_at = clock.now()

    existing = Counter(_tx_key(tx) for tx in store.all())
    new: list[Transaction] = []
    errors: list[RowError] = []
    duplicates = 0

    reader = csv.reader(io.StringIO(text, newline=""), delimiter=spec.delimiter)
    next(reader)  # заголовок, уже разобран
    prev_line = reader.line_num
    while True:
        line_no = prev_line + 1
        try:
            fields = next(reader)
        except StopIteration:
            break
        except csv.Error as exc:
            prev_line = reader.line_num
            if strict:
                raise StatementRowError(str(exc), line_no=line_no) from exc
            errors.append(RowError(line_no, str(exc)))
            continue
        prev_line = reader.line_num
        if _is_junk(fields):
            continue
        try:
            if len(fields) < needed:
                raise ValidationError("not enough fields")
            tx = parse(fields, idx, imported_at)
        except ValidationError as exc:
            if strict:
                raise StatementRowError(exc.args[0], line_no=line_no) from exc
            errors.append(RowError(line_no, exc.args[0]))
            continue
        key = _tx_key(tx)
        if existing[key] > 0:
            existing[key] -= 1
            duplicates += 1
            continue
        if categorizer is not None:
            category = categorizer.categorize(tx)
            if category is not None:
                tx = replace(tx, category=category)
        new.append(tx)

    if new:
        store.add_many(new)
    logger.info(
        "imported %d transactions from %s (%s, %d duplicates, %d errors)",
        len(new), path, fmt_name, duplicates, len(errors),
    )
    return ImportResult(
        format=fmt_name,
        encoding=encoding,
        added=len(new),
        duplicates=duplicates,
        errors=errors,
    )


def import_csv(
    path: str | os.PathLike[str],
    store: MemoryStore,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> int:
    """Импортирует выписку в store и возвращает число добавленных транзакций."""
    result = import_statement(path, store, strict=True, categorizer=categorizer, clock=clock)
    return result.added
